function run(){
  // Exhaustive minimax: f[e][n] = worst-case drops with e eggs and n untested floors.
  const N = 100;
  const f = [new Array(N + 1).fill(0), range(0, N), new Array(N + 1).fill(0)];
  for (let n = 1; n <= N; n++) {
    let best = Infinity;
    for (let x = 1; x <= n; x++) best = Math.min(best, 1 + Math.max(f[1][x - 1], f[2][n - x]));
    f[2][n] = best;
  }
  return f[2][N];
}
